#!/usr/bin/env bash
# parallel-loop.sh - Self-perpetuating wrapper for a named queue family.
# Usage: LOOP_NAME=parallel-a bash parallel-loop.sh
#
# Looks for overnight-queue-${LOOP_NAME}.yaml, runs it, then waits for
# overnight-queue-${LOOP_NAME}-b.yaml (generated by the last task), runs that,
# then waits for -c, etc. Loops forever until DEMO_DATE or killed.
#
# Launch example:
#   LOOP_NAME=parallel-a nohup bash scripts/parallel-loop.sh \
#     > logs/parallel-a-loop.log 2>&1 &

set -uo pipefail

DEMO_DATE="2026-12-31"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
OVERNIGHT="${SCRIPT_DIR}/run-local-overnight.sh"
LOGS_DIR="${SCRIPT_DIR}/logs"
LOOP_NAME="${LOOP_NAME:?LOOP_NAME env var required}"

mkdir -p "${LOGS_DIR}"

log() { echo "[$(date '+%Y-%m-%d %H:%M:%S')] $*"; }

# --------------------------------------------------------------------------
# PID lock - one instance per LOOP_NAME at a time.
# Prevents orphan stacking when the same loop is relaunched without killing
# the previous instance first.
# --------------------------------------------------------------------------
PID_FILE="${LOGS_DIR}/parallel-loop-${LOOP_NAME}.pid"
if [[ -f "${PID_FILE}" ]]; then
    OLD_PID=$(cat "${PID_FILE}" 2>/dev/null || echo "")
    if [[ -n "${OLD_PID}" ]] && kill -0 "${OLD_PID}" 2>/dev/null; then
        log "ERROR: parallel-loop ${LOOP_NAME} already running (PID ${OLD_PID}). Exiting."
        log "  To restart: kill ${OLD_PID} first, then re-run."
        exit 1
    fi
fi
echo "$$" > "${PID_FILE}"

# --------------------------------------------------------------------------
# Cleanup: remove PID file and kill the active overnight runner on exit.
# --------------------------------------------------------------------------
CURRENT_OVERNIGHT_PID=""
_parallel_cleanup() {
    rm -f "${PID_FILE}" 2>/dev/null || true
    if [[ -n "${CURRENT_OVERNIGHT_PID:-}" ]]; then
        kill -- "-${CURRENT_OVERNIGHT_PID}" 2>/dev/null || kill "${CURRENT_OVERNIGHT_PID}" 2>/dev/null || true
        wait "${CURRENT_OVERNIGHT_PID}" 2>/dev/null || true
    fi
}
trap '_parallel_cleanup' EXIT INT TERM HUP

# Sequence: a → b → c → d → e → f → ...
next_suffix() {
    local s="$1"
    case "$s" in
        "")  echo "b" ;;
        b)   echo "c" ;;
        c)   echo "d" ;;
        d)   echo "e" ;;
        e)   echo "f" ;;
        f)   echo "g" ;;
        g)   echo "h" ;;
        h)   echo "i" ;;
        i)   echo "j" ;;
        j)   echo "k" ;;
        k)   echo "l" ;;
        l)   echo "m" ;;
        m)   echo "n" ;;
        n)   echo "o" ;;
        o)   echo "p" ;;
        *)   echo "z" ;;
    esac
}

# Allow --start-suffix <x> to resume a loop at a specific suffix without
# cycling through all the already-completed queues before it.
START_SUFFIX=""
while [[ $# -gt 0 ]]; do
    case "$1" in
        --start-suffix) START_SUFFIX="$2"; shift 2 ;;
        *) shift ;;
    esac
done

SUFFIX="${START_SUFFIX}"  # first queue has no suffix: overnight-queue-parallel-a.yaml

while true; do
    if [[ "$(date +%Y-%m-%d)" > "${DEMO_DATE}" ]]; then
        log "Demo date ${DEMO_DATE} reached - stopping loop."
        exit 0
    fi

    if [[ -z "$SUFFIX" ]]; then
        QUEUE="${SCRIPT_DIR}/overnight-queue-${LOOP_NAME}.yaml"
    else
        QUEUE="${SCRIPT_DIR}/overnight-queue-${LOOP_NAME}-${SUFFIX}.yaml"
    fi

    # Wait up to 30 min for the queue file to appear
    waited=0
    while [[ ! -f "${QUEUE}" ]] && [[ $waited -lt 1800 ]]; do
        log "Waiting for ${QUEUE}... (${waited}s)"
        sleep 60; waited=$((waited + 60))
    done
    if [[ ! -f "${QUEUE}" ]]; then
        log "Queue never appeared - resetting to base queue and retrying."
        SUFFIX=""
        continue
    fi

    log "Running queue: $(basename ${QUEUE})"
    QUEUE="${QUEUE}" bash "${OVERNIGHT}" &
    CURRENT_OVERNIGHT_PID=$!
    wait "${CURRENT_OVERNIGHT_PID}" || true
    CURRENT_OVERNIGHT_PID=""
    log "Queue complete."

    # If the queue had no tasks (0-task run), sleep before advancing to avoid
    # rapid cycling through the alphabet when there's nothing to do.
    COMPLETED_FILE="${LOGS_DIR}/$(basename "${QUEUE}" .yaml).completed.txt"
    COMPLETED_COUNT=$(wc -l < "${COMPLETED_FILE}" 2>/dev/null || echo 0)
    if [[ "${COMPLETED_COUNT}" -eq 0 ]]; then
        log "Empty queue - sleeping 300s before checking next."
        sleep 300
    fi

    SUFFIX="$(next_suffix "$SUFFIX")"
done
